import Redis from 'ioredis'
import type { StreamEvent, PostMemConfig } from './types'

const GLOBAL_STREAM_KEY = 'chat:global'
const POLL_INTERVAL_MS = 200

export class StreamReader {
  private redis: Redis

  constructor(config: PostMemConfig['redis']) {
    this.redis = new Redis({
      host: config.host,
      port: config.port,
      db: config.db ?? 5,
      password: config.password,
      enableReadyCheck: false,
      maxRetriesPerRequest: null,
    })
  }

  async consume(
    onEvent: (event: StreamEvent) => void,
  ): Promise<void> {
    if (typeof onEvent !== 'function') {
      throw new Error('onEvent callback is required')
    }
    let lastId = '0-0'

    while (true) {
      const result = await this.redis.xread('STREAMS', GLOBAL_STREAM_KEY, lastId)

      if (result && result.length > 0) {
        const [, messages] = result[0]
        for (const [msgId, fields] of messages) {
          lastId = msgId
          const parsed: Record<string, string> = {}
          for (let i = 0; i < fields.length; i += 2) {
            parsed[fields[i]] = fields[i + 1]
          }

          const event: StreamEvent = JSON.parse(parsed.data)
          onEvent(event)
        }
      }

      await new Promise(resolve => setTimeout(resolve, POLL_INTERVAL_MS))
    }
  }

  async disconnect(): Promise<void> {
    await this.redis.quit()
  }
}
